import{j as e}from"./blog-pages-Br50gGHk.js";import{V as a}from"./_VerticalTemplate-JW8XmsJW.js";import"./accordion-CxdzlZyg.js";import"./index-Bi1CUJ2g.js";import"./dt-3d-models-BWSSvz5H.js";import"./index-DyQ3AqXO.js";const r={slug:"rail-infrastructure",industryDisplay:"Rail Infrastructure",industryShort:"freight and passenger rail operators, infrastructure managers, and rolling stock OEMs",heroSubhead:"Corporate NDT programs for rail welds, axle and wheelset integrity, bearing surveillance, and continuously-welded-rail (CWR) inspection. Built around EN 14587 (flash-butt rail welding), EN 14730 (aluminothermic rail welding), EN 13261 (axles), AAR M-101 (North American freight wheels), and the ultrasonic + magnetic-particle toolkit for axle and wheel maintenance.",primaryStandards:["EN 14587 (flash-butt rail welding)","EN 14730 (aluminothermic rail welding)","EN 13261 (railway axles)","EN 13262 (railway wheels)","AAR M-101 (freight car wheels)","AREMA Manual (track engineering)","ASTM A 531 (railroad rail UT)","ASNT Recommended Practice SNT-TC-1A"],methods:[{method:"Ultrasonic Testing — rail-head + axle + wheel ultrasonic inspection (manual + on-track UT trains)",levels:"Level I → III",roleFit:"Track inspectors, wheelset shop QC, on-track UT operators",codeRef:"EN 14587, EN 13261, ASTM A 531, AAR M-101"},{method:"Magnetic Particle Testing — axle + wheelset surface inspection (wet fluorescent)",levels:"Level I → II",roleFit:"Wheelset shop inspectors, locomotive overhaul QC",codeRef:"EN 13261 Annex C, ASTM E709, AAR M-101"},{method:"Liquid Penetrant Testing — rolling-stock structural welds + bogie frame QC",levels:"Level I → II",roleFit:"Carbuilder QC, rolling-stock overhaul inspectors",codeRef:"EN 15085 (railway vehicle welding), ASTM E165"},{method:"Eddy Current Testing — wheel-tread surface defect screening + axle near-surface",levels:"Level II",roleFit:"Wheelset shop inspectors, on-line wheel-condition surveillance teams",codeRef:"EN 13262 Annex B, ASTM E309"},{method:"Visual Testing — CWR + switch + crossing visual inspection",levels:"Level I → II",roleFit:"Track inspectors, switch &amp; crossing engineers",codeRef:"AREMA Chapter 4, ISO 17637"},{method:"Radiographic Testing — aluminothermic-weld inspection (selective use)",levels:"Level I → II",roleFit:"Specialist rail-weld QC",codeRef:"EN 14730, ASME V Article 2"},{method:"Acoustic emission + ultrasonic wayside detection — on-track surveillance",levels:"Level II + specialist",roleFit:"Wayside detector engineers, on-line integrity teams",codeRef:"EN 14587, internal IM written practice (Network Rail, BNSF, UP)"}],skillGaps:[{gap:"Track inspectors trained on visual + manual UT only, without the on-track UT train data-interpretation competence that defines modern CWR surveillance",impact:"Defects flagged by on-track UT trains cannot be confirmed manually; mobilisation cost without integrity benefit, or worse — defects accepted that drive derailment risk."},{gap:"Wheelset shop inspectors using AC yoke MT only, without WFMT (wet fluorescent magnetic particle) discipline on axle journals",impact:"EN 13261 Annex C compliance gap; rolling-stock overhaul packs rejected at operator acceptance — schedule slip and rework cost."},{gap:"Rolling-stock weld inspectors holding generic ISO 9606 welder qualification without EN 15085 railway-vehicle welding awareness",impact:"Railway-vehicle weld acceptance criteria misapplied; weld rejection rates 2–3× industry baseline on carbuilder QC."},{gap:"On-track UT train operators trained on a single OEM platform (Sperry / Pandrol / Rail.One) without cross-platform UT-data interpretation competence",impact:"Inability to second-source rail surveillance contractors; concentration risk on integrity-management programmes."},{gap:"Recurrent training cadence set at SNT-TC-1A's 5-year default rather than the 2-3 year cadence typical at infrastructure-manager audits",impact:"Network Rail / BNSF / UP / DB / Indian Railways audits flag stale qualification records — contractor accreditation suspended."}],tracks:[{role:"Track Integrity Inspector (CWR)",progression:"Level II UT + MT + VT, plus on-track UT train data-interpretation module",coreMethods:"UT, MT, VT, on-track UT",hoursTotal:"200–240 instructor-led + on-track shadow weeks"},{role:"Wheelset Shop Inspector",progression:"Level II UT + MT (WFMT) + ECT + PT for axles + wheels",coreMethods:"UT, MT (WFMT), ECT, PT",hoursTotal:"220–260 instructor-led + shop residency"},{role:"Rolling-Stock Welding Inspector",progression:"Level II UT + MT + PT + VT, plus EN 15085 awareness module",coreMethods:"UT, MT, PT, VT + EN 15085",hoursTotal:"200–240 instructor-led"},{role:"Rail-Weld Inspector (Flash-butt + Aluminothermic)",progression:"Level II UT + RT + MT, plus EN 14587 / EN 14730 module",coreMethods:"UT, RT, MT + EN 14587 + EN 14730",hoursTotal:"180–220 instructor-led"},{role:"Wayside / On-Line Surveillance Engineer",progression:"Level II UT + acoustic emission + ECT for wheel surveillance",coreMethods:"UT, AE, ECT",hoursTotal:"160–200 instructor-led + wayside shadow"}],pricing:[{headcount:"10–24 engineers",perHead:"$1,200–$2,400 per head",notes:"Standard methods + rail-specific written practice + EN 14587 / EN 13261 module."},{headcount:"25–49 engineers",perHead:"$1,050–$2,100 per head",notes:"Multi-method tracks across track + wheelset + rolling stock."},{headcount:"50–99 engineers",perHead:"$900–$1,850 per head",notes:"Multi-depot operator programme; dedicated lead instructor."},{headcount:"100+ engineers",perHead:"POA — typically $750–$1,600 per head",notes:"Multi-region infrastructure-manager annual contract; operator-specific written-practice bridging included."}],deliveryNote:"Rail cohorts are dominated by hybrid delivery, with on-track and wayside practicals run as separate workshops during pre-planned possession windows. Theory on the LMS during the planning quarter, wheelset shop practicals at the operator's own depot, on-track UT data-interpretation sessions on actual rail surveillance data sets supplied under NDA by the customer. EN 14730 aluminothermic-weld practicals run on the customer's spec rail in a controlled welding bay so essential-variable transfer is genuine.",complianceFootnote:"Rail infrastructure managers (Network Rail, BNSF Railway, Union Pacific, CSX, Norfolk Southern, DB Netz, SNCF Réseau, Indian Railways, China Railway, ProRail, Rete Ferroviaria Italiana) all run contractor-accreditation audits to slightly different layouts but ask for the same underlying evidence — SNT-TC-1A or EN ISO 9712 written practice references, training hours mapped to Recommended Hours, exam grade sheets retained, vision and OJT logs current, EN 15085 welder-supervisor records for rolling-stock work, and EN 14587 / EN 14730 records for rail welding. Our delivery captures all of that automatically and exports it in the layout your infrastructure manager expects.",caseStudy:{headline:"Class-I freight railroad (North America) — 38-engineer multi-method cohort, 11-week programme",body:"A Class-I North American freight railroad managing a 30,000-mile network needed to certify 38 in-house inspectors across UT Level II, MT (WFMT) Level II, ECT Level II for wheel-tread surveillance, plus the on-track UT data-interpretation module for CWR maintenance, ahead of a major spring track-maintenance campaign. Atlantis NDT delivered a hybrid cohort over 11 weeks: 5 weeks LMS theory in parallel with normal duties, 4 weeks on-site practical split between a regional wheelset shop and a track-maintenance base, then a 2-week on-track UT data-interpretation block using historical rail-surveillance data sets supplied under NDA. First-attempt pass rate across all four methods averaged 92%. The railroad's FRA contractor-accreditation audit closed with no inspector-qualification findings, and total per-head cost landed 33% below the open-enrolment route the railroad had previously used."},cityLinks:[{slug:"chicago",label:"Chicago"},{slug:"london",label:"London"}],wordCountHint:"Rail-infrastructure NDT corporate training is one of the most code-fragmented verticals in the inspection world — different code stacks for North American freight (AAR M-101 wheels + AREMA Manual track), European passenger and freight (EN 14587 rail welding + EN 13261 axles + EN 15085 rolling-stock welding), and the converging code base in major emerging-market operators (Indian Railways, China Railway, the GCC rail corridors). Our rail cohorts are built for the infrastructure managers and operators actually managing the assets — Network Rail in the UK, BNSF Railway and Union Pacific in North America, DB Cargo and Deutsche Bahn in Germany, SNCF in France, Indian Railways and Dedicated Freight Corridor Corporation in India, China Railway, Etihad Rail in the UAE, and Saudi Arabia Railways. The skill gap that dominates rail training procurement is the gap between manual track inspection (visual + manual UT) and the on-track UT train data-interpretation competence that defines modern CWR (continuously-welded-rail) surveillance. On-track UT trains generate enormous data volumes that need expert interpretation, and the gap between an inspector who can run the UT train and an inspector who can interpret the data is the difference between effective and ineffective surveillance. We run on-track UT data-interpretation modules using historical surveillance data sets supplied under NDA by the customer so essential-variable transfer is genuine. The second skill gap, especially common at wheelset shops, is the gap between AC yoke MT competence (which most candidates have from a general-engineering background) and the WFMT (wet fluorescent magnetic particle) discipline required by EN 13261 Annex C for axle-journal inspection. Our wheelset shop module is delivered as a residency at the customer's own depot so engineers learn WFMT on the actual axles they will be inspecting in service. The third area where rail diverges from other verticals is the EN 15085 railway-vehicle welding qualification stack — rolling-stock OEMs (Bombardier, Alstom, Siemens Mobility, Hitachi Rail, CRRC, Stadler) all enforce EN 15085 above and beyond general ISO 9606 welder qualification, and our EN 15085 awareness module is delivered as a stand-alone 3-day workshop. Recurrent training cadence in rail is shorter than the SNT-TC-1A 5-year default — most infrastructure managers require 2-3 year recertification, and our recurrent calendar is built to fit that cadence. Send the asset mix (track / wheelset / rolling-stock / rail-welding), the infrastructure manager, and headcount — we respond inside two business days with a written training plan and indicative quote, with an SNT-TC-1A + EN ISO 9712 dual-mapped written practice ready to layer on top of your own corporate written practice."};function c(){return e.jsx(a,{config:r})}export{c as default};
